styl:
.b-iq-hero-28 u + .body .gmail-blend-screen {  background: #000;
  mix-blend-mode: screen;  }
.b-iq-hero-28 u + .body .gmail-blend-diff {  background: #000;
  mix-blend-mode: difference;  }
.bgr-image.b-iq-hero-28 {  background: url("https://fsms.quadcode.com/storage/public/d6/rs/39rursrq72d919c0/2-2-1-back.png") center top no-repeat;
  background-size: cover;
  background-color: #000;  }
.b-iq-hero-28 .w280 {  width: 100%;
  max-width: 280px;  }
@media screen and (max-width: 600px) {
  .b-iq-hero-28 .w280 {  max-width: 100% !important;  }
}
.brad-full.b-iq-hero-28 {  border-radius: 32px !important;  }
.b-iq-hero-28 .butt-link {  font-size: 18px;
  line-height: 27px;
  font-weight: 700;
  text-transform: none;
  text-decoration: none;
  color: #f9f9f9;
  display: block;
  padding: 16px 0 16px;
  text-align: center;
  letter-spacing: 0px;  }
.b-iq-hero-28 .white-title {  font-family: Helvetica !important;
  font-weight: 700;
  font-size: 42px;
  line-height: 52px;
  color: #f9f9f9;
  word-break: break-word;
  padding-right: 30px;  }
@media screen and (max-width: 600px) {
  .b-iq-hero-28 .white-title {  font-size: 26px !important;
    line-height: 32px !important;  }
}
.b-iq-hero-28 .white-text {  font-family: Helvetica !important;
  font-style: normal;
  font-weight: 400;
  font-size: 18px;
  line-height: 27px;
  color: #fff;
  padding-right: 20px;  }
@media screen and (max-width: 600px) {
  .b-iq-hero-28 .white-text {  padding-right: 0 !important;  }
}
.b-iq-hero-28 .pb16 {  padding-bottom: 16px;  }
.b-iq-hero-28 .h-24 {  font-size: 8px;
  line-height: 24px;
  height: 24px;  }
